<script setup>
import { computed, onMounted, ref } from 'vue'
import { Command, LayoutGrid, Plus, RotateCcw, Save, ShieldCheck, Trash2 } from '@lucide/vue'
import { applySpatialAction, applySpatialCommand, createSpatialWorkspace, getSpatialWorkspace, listSpatialWorkspaces } from '../api'

const items=ref([]), current=ref(null), loading=ref(true), busy=ref(false), error=ref(''), title=ref('技能训练空间'), command=ref('')
const cards=computed(()=>current.value?.layout?.cards||[])
function msg(e,f){const d=e?.response?.data?.detail;return d?.message||e?.message||f}
async function load(){loading.value=true;error.value='';try{const data=await listSpatialWorkspaces();items.value=data.items;if(items.value.length)await open(items.value[0].id)}catch(e){error.value=msg(e,'空间工作区加载失败')}finally{loading.value=false}}
async function open(id){current.value=await getSpatialWorkspace(id);items.value=items.value.map(x=>x.id===id?current.value:x)}
async function create(){busy.value=true;error.value='';try{const row=await createSpatialWorkspace({title:title.value});items.value=[row,...items.value];await open(row.id)}catch(e){error.value=msg(e,'创建失败')}finally{busy.value=false}}
async function action(name,args={}){if(!current.value)return;busy.value=true;error.value='';try{current.value=await applySpatialAction(current.value.id,{action:name,arguments:args,expected_version:current.value.lock_version});items.value=items.value.map(x=>x.id===current.value.id?current.value:x)}catch(e){error.value=msg(e,'布局更新失败')}finally{busy.value=false}}
async function runCommand(){if(!command.value.trim()||!current.value)return;busy.value=true;error.value='';try{current.value=await applySpatialCommand(current.value.id,{command:command.value,expected_version:current.value.lock_version});command.value='';items.value=items.value.map(x=>x.id===current.value.id?current.value:x)}catch(e){error.value=msg(e,'命令被拒绝')}finally{busy.value=false}}
function move(card,dx,dy){action('move_card',{card_id:card.id,x:Math.max(0,Math.min(980,card.x+dx)),y:Math.max(0,Math.min(600,card.y+dy))})}
onMounted(load)
</script>
<template>
<main class="spatial" data-testid="spatial-workspace">
 <header><div><p class="eyebrow">SPATIAL LEARNING CANVAS</p><h1>空间学习工作区</h1><p>布局由服务端逐版本保存，可在不同设备恢复；命令只执行白名单动作。</p></div><div class="trust"><ShieldCheck :size="18"/><span>确定性动作</span><small>不调用外部模型</small></div></header>
 <p v-if="error" class="notice err">{{error}}</p><p v-if="loading" class="notice">正在恢复跨设备布局...</p>
 <template v-else>
  <section class="toolbar"><input v-model="title" aria-label="空间名称" maxlength="256"/><button :disabled="busy" @click="create"><Plus :size="15"/>新建空间</button><select v-if="items.length" :value="current?.id" aria-label="选择空间" @change="open($event.target.value)"><option v-for="x in items" :key="x.id" :value="x.id">{{x.title}} · v{{x.version_number}}</option></select></section>
  <section v-if="current" class="command"><Command :size="17"/><input v-model="command" aria-label="白名单命令" placeholder="例如：新增卡片：复习向量检索" @keyup.enter="runCommand"/><button :disabled="busy" @click="runCommand">执行</button><button title="自动整理" :disabled="busy" @click="action('auto_layout')"><LayoutGrid :size="15"/></button><button title="撤销" :disabled="busy||current.version_number===1" @click="action('undo')"><RotateCcw :size="15"/></button></section>
  <div v-if="current" class="grid"><aside><div class="section-title"><strong>版本历史</strong><small>{{current.history.length}} 项</small></div><ol><li v-for="v in current.history" :key="v.id"><b>v{{v.version_number}}</b><span>{{v.action_summary}}</span><small>{{v.content_hash.slice(0,8)}}</small></li></ol></aside>
   <section class="canvas-shell"><div class="canvas-meta"><span>{{current.title}}</span><small>v{{current.version_number}} · {{cards.length}} 张卡片 · lock {{current.lock_version}}</small></div><div class="canvas" data-testid="spatial-canvas">
    <article v-for="card in cards" :key="card.id" :style="{left:`${card.x/12}%`,top:`${card.y/7.6}%`}" data-testid="spatial-card"><div><small>{{card.kind}} · {{card.id}}</small><strong>{{card.title}}</strong></div><div class="card-actions"><button title="左移" @click="move(card,-40,0)">←</button><button title="右移" @click="move(card,40,0)">→</button><button title="上移" @click="move(card,0,-40)">↑</button><button title="下移" @click="move(card,0,40)">↓</button><button title="删除卡片" @click="action('remove_card',{card_id:card.id})"><Trash2 :size="12"/></button></div></article>
    <div v-if="!cards.length" class="empty"><Save :size="22"/><strong>空白画布</strong><span>输入“新增卡片：内容”建立第一张学习卡片。</span></div>
   </div></section></div>
 </template>
</main>
</template>
<style scoped>
.spatial{max-width:1220px;margin:0 auto;color:#25312a}.spatial header{display:flex;justify-content:space-between;gap:24px;padding-bottom:20px;border-bottom:1px solid #d9e1dc}.eyebrow{margin:0 0 6px;color:#47705a;font-size:10px;font-weight:800}.spatial h1{margin:0;font-size:24px;letter-spacing:0}.spatial header p:last-child{margin:6px 0 0;color:#69756d;font-size:12px}.trust{display:grid;grid-template-columns:auto 1fr;align-content:center;min-width:200px;padding:11px 13px;border:1px solid #c9ddd0;background:#f1f7f3;color:#335c42}.trust svg{grid-row:1/3;margin-right:8px}.trust span{font-size:11px;font-weight:800}.trust small{font-size:9px}.notice{padding:10px;background:#f4f6f4;font-size:11px}.err{background:#fff0ed;color:#8a4339}.toolbar,.command{display:flex;gap:8px;margin-top:14px}.toolbar input,.toolbar select,.command input{height:36px;padding:0 10px;border:1px solid #d2dbd5;background:#fff}.toolbar input{width:190px}.toolbar select{flex:1}.toolbar button,.command button,.card-actions button{display:inline-flex;align-items:center;justify-content:center;gap:5px;border:1px solid #cbd7cf;background:#fff;color:#35483c}.toolbar button,.command button{min-height:36px;padding:0 11px}.command{align-items:center;padding:10px;background:#f3f6f4}.command input{flex:1}.grid{display:grid;grid-template-columns:220px minmax(0,1fr);gap:12px;margin-top:12px}.grid aside,.canvas-shell{border:1px solid #dae2dc;background:#fff}.grid aside{padding:12px}.section-title,.canvas-meta{display:flex;justify-content:space-between;gap:10px;padding-bottom:10px;border-bottom:1px solid #e5eae7;font-size:11px}.section-title small,.canvas-meta small{color:#7d8881;font-size:9px}.grid ol{margin:8px 0 0;padding:0;list-style:none}.grid li{display:grid;grid-template-columns:30px 1fr;gap:3px 7px;padding:8px 3px;border-bottom:1px solid #edf0ee;font-size:9px}.grid li b{grid-row:1/3}.grid li small{color:#879089}.canvas-shell{padding:12px}.canvas{position:relative;min-height:570px;margin-top:10px;overflow:hidden;background-color:#f7f9f7;background-image:linear-gradient(#e6ebe7 1px,transparent 1px),linear-gradient(90deg,#e6ebe7 1px,transparent 1px);background-size:24px 24px}.canvas article{position:absolute;width:min(180px,22%);min-height:86px;padding:10px;box-sizing:border-box;border:1px solid #cbd9cf;background:#fff;box-shadow:0 3px 10px #253b2c12}.canvas article small,.canvas article strong{display:block}.canvas article small{color:#79857c;font-size:8px}.canvas article strong{margin-top:6px;font-size:11px}.card-actions{display:flex;gap:3px;margin-top:10px}.card-actions button{width:23px;height:23px;padding:0;font-size:11px}.empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#7a867e}.empty strong{margin-top:8px;font-size:12px}.empty span{margin-top:4px;font-size:9px}@media(max-width:800px){.spatial header{flex-direction:column}.trust{min-width:0}.grid{grid-template-columns:1fr}.grid aside{max-height:150px;overflow:auto}.canvas{min-height:520px}.canvas article{width:42%}.toolbar{flex-wrap:wrap}.toolbar input,.toolbar select{width:100%;flex:auto}.command{flex-wrap:wrap}.command input{min-width:100%}}@media(max-width:430px){.canvas{display:grid;grid-template-columns:1fr;align-content:start;gap:8px;min-height:480px;padding:10px}.canvas article{position:static;width:100%;min-height:0;padding:9px}.card-actions button{width:25px}.grid aside{display:none}.empty{position:static;min-height:420px}}
</style>
